<script setup lang="ts">import type { Plan } from '../types';defineProps<{plan:Plan;selected:boolean}>();defineEmits<{toggle:[id:number]}>();const money=(n:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);</script>
<template><article class="plan-card" :class="{chosen:selected}"><div class="plan-top"><span class="carrier">{{plan.carrier}}</span><span class="plan-check">{{selected?'Selected':'Available'}}</span></div><h3>{{plan.name}}</h3><p class="premium"><strong>{{money(plan.annual_premium/12)}}</strong><span>/ month</span></p><div class="plan-stats"><div><span>Deductible</span><b>{{money(plan.deductible)}}</b></div><div><span>Office co-pay</span><b>{{money(plan.copay)}}</b></div><div><span>Plan coverage</span><b>{{plan.coverage_percent}}%</b></div></div><button class="secondary-button" @click="$emit('toggle',plan.id)">{{selected?'Remove from compare':'Compare plan'}}</button></article></template>
